const cds = require('@sap/cds');
const { DELETE } = cds.ql;
const { readSettings, findIncompleteMessages } = require('./enrichment');

const LOG = cds.log('GenAI');

// Name of the task of one message in the queue. A task name is unique: scheduling it again while
// the task is waiting for a retry does not create a second task.
const TASK_PREFIX = 'enrich-';
const taskName = ID => `${TASK_PREFIX}${ID}`;

// Called before every READ of the customer messages (srv/service.js, generated by SAP Build Code).
// The AI is not called here: for each message that misses AI fields a task is put into the
// persistent queue of EnrichmentService, which calls the AI after the request and retries it
// when it fails. So the READ is not slowed down by the AI and a failing AI does not break it.
module.exports = async function(request) {
	// cds.genai.enabled switches the enrichment off for the whole application (it is off in the test profile).
	if (cds.env.genai?.enabled === false) return;

	let incomplete;
	try {
		const settings = await readSettings();
		if (!settings.autoEnrichment) {
			LOG.debug('Automatic enrichment is switched off in the settings');
			return;
		}
		incomplete = await findIncompleteMessages();
	} catch (error) {
		LOG.error('Failed to retrieve customer messages', error.message);
		return request.reject(500, 'Failed to retrieve customer messages');
	}

	if (!incomplete.length) return;

	try {
		await dropExhaustedTasks();
		const enrichment = await cds.connect.to('EnrichmentService');
		for (const ID of incomplete) await enrichment.schedule('enrichMessage', { ID }).asTask(taskName(ID));
	} catch (error) {
		// The messages are read as they are; the next READ schedules the tasks again.
		LOG.error('Failed to schedule the enrichment of customer messages', error.message);
	}
};

// A task that has used up its attempts stays in the queue table and is not run again. It is removed,
// so that the next READ schedules the message afresh, for example after the AI service was down for hours.
async function dropExhaustedTasks() {
	const { maxAttempts } = cds.env.requires.queue;
	if (!maxAttempts) return;
	await DELETE.from('cds.outbox.Messages').where(`task like '${TASK_PREFIX}%' and attempts >= ${Number(maxAttempts)}`);
}
